CREATE TABLE app_user (id BIGINT AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(160) NOT NULL,username VARCHAR(120) NOT NULL UNIQUE,email VARCHAR(180) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role VARCHAR(30) NOT NULL,enabled BOOLEAN NOT NULL DEFAULT TRUE,must_change_password BOOLEAN NOT NULL DEFAULT FALSE,reset_token VARCHAR(100),reset_token_expires_at DATETIME,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
